 update(86,sources=['proposal/interiors/leisure/garage.json','proposal/planning/REQUIRED-ACTIONS.md'])
 update(96,sources=['revisions/principal-gable-wall-2026-09-28/STATUS.md','scripts/interiors/principal_gable_wall.py'])
 update(97,sources=['revisions/build-speed-2026-09-25/STATUS.md'] if (root/'revisions/build-speed-2026-09-25/STATUS.md').exists() else ['scripts/build/build_extension_proposal.py'])
 update(98,sources=['scripts/interiors/proposal_interior_details.py','revisions/interiors-overnight-2026-09-27/internal-reveals-compact.json'])
 update(99,sources=['scripts/publication/model_delivery.py','walkthrough/src/model-delivery.js'])
 update(100,sources=['revisions/interiors-overnight-2026-09-27/STATUS.md','revisions/principal-gable-wall-2026-09-28/STATUS.md','proposal/START-HERE.md'])
 # Study plans are evidence of the current layout, not drawings of these proposals.
 plans={'Entrance & hall':'arrival','Kitchen & garden dining':'kitchen','Formal lounge & dining':'formal','Office':'office','Principal bedroom':'principal','Principal bathroom & wardrobe':'dressing-bath','Other bedrooms':'sidebed','Shared bathrooms & cloakroom':'guestbath','Landings & loft':'hobby','Gym':'gym','Cinema':'cinema','Wine bar & games':'bar','Utility':'utility','Garage & parking':'garage','Pool & garden':'poolgarden','Roof terrace':'terrace','Workshop':'workshop','TV lounge':'tv-lounge','Upstairs family lounge':'family','Loft bedroom & ensuite':'loftsuite','Summer house & changing':'gardenhouse'}
 specific={36:'loftsuite',37:'bedroom3',38:'bedroom4',39:'guest',40:'bedroom2',42:'familybath',46:'landings',49:'loftsuite'}
 for x in items:
  n=int(x['id'][3:]);slug=specific.get(n,plans.get(x['area']))
  if slug:
   plan=f'revisions/brochure-spatial-2026-09-28/plans/{slug}.svg'
   if (root/plan).exists():x['plan']=plan;x['planCaption']='Existing brochure concept plan — shows the baseline, not this proposed improvement. Dimensions await survey.'
  for s in x['sources']:assert (root/s).is_file(),s
 refs={
  'desk':{'title':'HSE: workstation space, glare and screen position','url':'https://www.hse.gov.uk/pubns/indg36.pdf'},
  'planning':{'title':'Sevenoaks: Residential Extensions SPD (design and amenity guidance)','url':'https://www.sevenoaks.gov.uk/downloads/download/141/residential_extensions_spd'},
  'comfort':{'title':'Government: Approved Document O overview (check project applicability separately)','url':'https://www.gov.uk/government/publications/overheating-approved-document-o'},
 }
 for n in (18,19,24):by[f'AH-{n:03}']['references']=[refs['desk']]
 for n in (29,31,43,45,78,81,83,85,86):by[f'AH-{n:03}']['references']=[refs['planning']]
 by['AH-089']['references']=[refs['comfort']]
 for x in items:
  if 'An equipment' not in x['tradeoff']:x['tradeoff']=x['tradeoff'].replace('A equipment','An equipment')

 # Measured comparisons are proposal evidence, distinct from baseline plans.
 for n,slug in [(54,'cinema'),(58,'games')]:
  x=by[f'AH-{n:03}']
  if x.get('plan'):x['sources'].append(x['plan'])
  x['plan']=f'revisions/whole-house-review-2026-09-29/{slug}-comparison.svg'
